def _carregar_padroes() -> None:
    conexao = op.get_bind()
    ordem_book = 0
    for ordem, (estrategia, peso, books) in enumerate(_PADROES, 1):
        estrategia_id = conexao.execute(
            sa.text("INSERT INTO estrategia (nome, peso, ordem) VALUES (:n, :p, :o) RETURNING id"),
            {"n": estrategia, "p": peso, "o": ordem},
        ).scalar_one()
        for book, peso_book, classes in books:
            ordem_book += 1
            book_id = conexao.execute(
                sa.text("INSERT INTO book (estrategia_id, nome, peso, ordem) VALUES (:e, :n, :p, :o) RETURNING id"),
                {"e": estrategia_id, "n": book, "p": peso_book, "o": ordem_book},
            ).scalar_one()
            for classe in classes:
                conexao.execute(
                    sa.text("INSERT INTO classe_book (classe, book_id) VALUES (:c, :b)"), {"c": classe, "b": book_id}
                )


